import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.BwzYn71E.js";const c=JSON.parse('{"title":"Establishing a Customer Support (Free Consultation and Q&A) Department","description":"","frontmatter":{"translationSource":{"title":"建立售后\\\\(义诊答疑\\\\)部门","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}]]},"headers":[],"relativePath":"establishing-a-customer-support-department.md","filePath":"logistics/src/page-AnG8YkyaK2VGhXykemIDer.md"}'),n={name:"establishing-a-customer-support-department.md"};function r(i,e,p,l,u,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="establishing-a-customer-support-free-consultation-and-q-a-department" tabindex="-1">Establishing a Customer Support (Free Consultation and Q&amp;A) Department <a class="header-anchor" href="#establishing-a-customer-support-free-consultation-and-q-a-department" aria-label="Permalink to &quot;Establishing a Customer Support (Free Consultation and Q&amp;A) Department&quot;">​</a></h1><blockquote><p>Source page ID: <code>AnG8YkyaK2VGhXykemIDer</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Due to the summary of issues in the <a href="/endfield-skydoc/issues-with-publishing-results">results-publication process</a>, we decided to establish a customer-support department.</p><p>Collect the names of people involved in after-sales support.</p><p><span class="mark-grey">#言: After-sales support and Q&amp;A should be able to trace root causes and resolve most possible issues. In practice, this requires using reports to backtrack problems with reasonable accuracy, a clear understanding of every module&#39;s functions, and a basic understanding of automatic balancing/adaptive devices. It also requires some spare time to handle questions and learn the necessary knowledge.</span></p><p><span class="mark-grey">#沃: Huh, what about the livestream? 🤔 Wasn&#39;t it written in?</span></p><p><span class="mark-grey">#东: Personally, I think livestreaming is both a troubleshooting method and a safeguard; if you log into someone&#39;s account, stream it to leave a record (</span><span class="mark-grey"><s>? I still feel like venting. All these days of support really have brought plenty of entertainment (?) and a sense of self-worth. Most people can have their problems solved even without reading the docs, but then reading them becomes the support staff&#39;s job (I have looked through the FAQ null times). We send them a screenshot and the problem is solved; if that fails, logging into the account usually finishes the job. What scares me is people who ignore instructions, have their own ideas (not little creative tweaks), or cannot communicate (immortals talking past each other). By comparison, little tweaks do not seem so scary (?!) I came here to solve problems, help people and learn the techniques, so why should I keep losing my temper?</s></span><span class="mark-grey">(Friends who have read this far can probably understand the current state of support x-x.)</span></p><p><span class="mark-grey">#东: The comment section simply is not a place where troubleshooting can be done.</span></p><p><span class="mark-grey">#jnk: </span><a href="/endfield-skydoc/issues-with-publishing-results">Summary of Issues in the Results-Publication Process</a></p><p><span class="mark-grey">#Disadvantage: Current troubleshooting involves many repetitive tasks, such as reminding people about reports. We need ways to avoid these—for example, group-entry questions and announcements explaining the prerequisites for support—to improve efficiency and handle potentially large numbers of requests.</span></p><p><span class="mark-grey">#言: In that case, could we make a bot that monitors group chat and does an initial check for matches with common questions? Ideally, mooch off some free AI (</span></p><p><span class="mark-grey">#东: </span><span class="mark-grey"><s>Feels like QQ Group Assistant would do (?</s></span><span class="mark-grey">Given the restrictions of </span><span class="mark-grey"><u>HarmonyOS</u></span><span class="mark-grey">, I do not think QQ Group Assistant is viable.</span><span class="mark-grey"><s>HarmonyOS is terrible</s></span></p><p>Establish a relevant group chat.</p><p><span class="mark-grey">The group number should not be posted here; relevant personnel should manually review and invite members.</span></p><p><span id="source-block-DheeoJbZgduO0Z9vZfkSv3"></span></p><h2 id="customer-support-q-a-guidelines-to-be-written" tabindex="-1">Customer Support / Q&amp;A Guidelines (to be written <a class="header-anchor" href="#customer-support-q-a-guidelines-to-be-written" aria-label="Permalink to &quot;Customer Support / Q&amp;A Guidelines (to be written&quot;">​</a></h2><p><span class="mark-grey">#东: First, support staff must not snap at users first, and should not snap at them at all—at least be civil when scolding people. Second, if another support person starts snapping, stop them promptly; troubleshooting is not a shouting match. Finally, respect every user, even someone who randomly changes the line and ignores instructions. All beings are equal under compassion. We can choose not to answer, but if we answer, take responsibility and do it properly.</span></p><p><span class="mark-grey">#言: If you do not want to answer, you can ignore it. But once you answer, be prepared to deal with the follow-up questions, or identify clearly who will follow up when handing off a problem you cannot solve. Do not vent or abandon it halfway. (#东: Agreed.)</span></p><p><span id="source-block-MCp3KAJDxAeiKPQNN5mI57"></span></p><h2 id="user-guidelines-to-be-written" tabindex="-1">User Guidelines (to be written <a class="header-anchor" href="#user-guidelines-to-be-written" aria-label="Permalink to &quot;User Guidelines (to be written&quot;">​</a></h2><p><span class="mark-grey">#言: If you have a problem, go to the group chat or the Q&amp;A site first and take the support staff&#39;s answers as authoritative (they are not necessarily absolutely correct, but there is no denying that they are more familiar with production lines than most people and can transfer you to a developer at any time). In other words, do not readily trust replies from other channels, and do not stubbornly insist on your own view with the support staff.</span></p><p><span class="mark-grey"><s>#言: You should look more at the videos and documents for the current production line (documents are normally where blueprints are obtained; note that blueprint codes that appear in the comment section may not be the latest version) and at the videos. The videos show almost every necessary operation, and the documents already answer many common questions. Asking questions that could have been resolved through the above means is an unnecessary burden on the support staff (even if you cannot understand all of it, having made the effort greatly reduces their burden). Please do not consume our enthusiasm and goodwill like this.</s></span></p><p><span class="mark-grey">#言: In principle, we do not accept simple questions asked without first consulting the videos, documentation or in-game encyclopedia. These readily accessible sources answer many common questions. Asking may take you only a few sentences, but large numbers of people repeatedly asking the same questions consume enormous amounts of the support staff&#39;s energy, enthusiasm and goodwill (and, in my view, this is rather unethical). To leave staff enough energy for difficult cases that need them more, questions easily answered by those sources may be ignored. Other helpful group members may answer, but we are not responsible for the accuracy of those answers.</span></p><p>#JMY: Horror, gore, sexually suggestive and pornographic content are strictly forbidden in the group. The first offense means a 1-day mute; the second means removal and blacklisting.</p><p><span class="mark-grey">#Disadvantage: Removing people once troubleshooting ends could avoid this to some extent. These rules seem more suited to the main group (? #东: That seems a bit hard on people, and sometimes it is difficult to tell whether troubleshooting has finished (? Wouldn&#39;t that make us an actual hospital?</span><br><span class="mark-grey">#言: Is there no room for a warning? Isn&#39;t that too strict? It is also hard to tell how many times someone has broken the rule. We should not make unenforceable rules.</span></p><p>#jmy: We could set up a separate chat group and move people there after troubleshooting to free up places in the support group.</p><p>#disadvantage: A troubleshooting group really has to do troubleshooting. <span class="mark-grey">Damn, why didn&#39;t you say so earlier? #jmy #东: Damn, why didn&#39;t you say so earlier? #151: Damn, why didn&#39;t you say so earlier?</span></p><p><span class="mark-grey">#Disadvantage: Modifying a production line without fully understanding how it works is strictly forbidden. Asking for support after your own modifications break the factory wastes support staff&#39;s time.</span><br> #言: Or at least explain what modifications you have made.</p><p><span class="mark-grey">#言: Keep unrelated discussion out of the AIC troubleshooting group, including other games, Arknights, gacha, combat rotations and zipline exploits. Mutes may be issued depending on the circumstances.</span></p><p><span class="mark-grey">#东: No attacking support staff</span><span class="mark-grey"><s>—support staff are lower-realm pigfolk</s></span><span class="mark-grey"><br> #言: Why not simply ban personal attacks in the group? Whether against new or old members, support staff, developers or 改区 [unresolved slang]. Administrators decide what counts as a personal attack.</span></p><p><span id="source-block-D4gufk7H4xiLthYE7JHT6d"></span></p><h2 id="qq-group-announcement-subject-to-change" tabindex="-1">QQ Group Announcement (Subject to Change <a class="header-anchor" href="#qq-group-announcement-subject-to-change" aria-label="Permalink to &quot;QQ Group Announcement (Subject to Change&quot;">​</a></h2><p><span class="mark-grey">#东: Is it possible nobody reads from here onward (? #言: Then spell it out clearly below: what gets ignored, what we take no responsibility for, and what gets people kicked out.</span></p><p><span class="mark-red"><strong>Because this announcement is excessively long, enforcement cannot in practice be as strict as the wording suggests. In most cases, it serves only as grounds for a warning.</strong></span></p><p>Before asking the group for help, we encourage you to watch the videos, read the docs or consult the in-game encyclopedia (apparently this effectively improves the support staff&#39;s opinion of you). Video links are included in the docs, so only the documentation link is given here:<br><a href="/endfield-skydoc/1-5-automatic-maximum-gross-production">1.5 Automatic Maximum Gross Production</a><br> If you want to learn more about how this factory works, the developers have included links to the required reading in that document. Questions arising from studying AIC principles are especially welcome.</p><p>When asking the group for troubleshooting, always show the following items; this greatly improves efficiency:<br> (Star items in the production report to pin them for easy display.) Originium Ore, Ferrium Ore, Cuprium Ore, Cuprium, Ferrium Powder, Cuprium Powder, Dense Originium Powder, Hetonite, Xiranite, Heavy Xiranite, Xircon, Pyrrolite, Separator Core, Cuprium Solution, Cuprium Gas, Hetonite Gas, Pyrrolite Gas, SC Wuling Battery (default order, ascending). Ignoring this may annoy support staff or lead to your question being ignored.</p><p>Sensitive content is forbidden, including horror, gore, sexually suggestive content and financial transactions. Violations lead to immediate removal. Keep unrelated discussion to a minimum, including other games, Arknights, gacha, combat rotations and zipline exploits; mutes may be issued depending on the circumstances.</p><p>Treat the answers from support staff (currently group administrators, excluding the owner) as authoritative. They are not necessarily absolutely correct, but they are more familiar with production lines than most people and can transfer you to developers at any time. Do not readily trust replies from other channels or stubbornly insist on your own view with support staff.</p><p>In principle, we do not accept simple questions asked without first consulting the videos, documentation or in-game encyclopedia. These readily accessible sources answer many common questions. Asking may take you only a few sentences, but large numbers of people repeatedly asking the same questions consume enormous amounts of the support staff&#39;s energy, enthusiasm and goodwill. To leave staff enough energy for difficult cases that need them more, questions easily answered by those sources may be ignored. Other helpful group members may answer, but we are not responsible for the accuracy of those answers.</p><p>Personal attacks are forbidden, whether against new or old group members, support staff or developers. Anyone can report them to members and administrators through a private temporary chat. Confirmed violations lead to a lengthy mute. Please pass on knowledge and kindness rather than hostility, and take responsibility for your words and actions.</p><p>To keep places available for newcomers and new questions, members who have not spoken for a week will be removed at unspecified times each week. If you want to study AIC further, contact an administrator or the group owner through a temporary chat to apply.</p><p>Support staff may ignore questions they do not wish to answer. Once you choose to answer, however, respect the other person&#39;s difficulty and questions throughout and take full responsibility for your assistance. Before transferring a problem you cannot solve, identify the next person responsible and clearly inform the questioner. Do not vent or abandon the issue halfway. If either party breaks the rules, anyone, including those involved, may report it to an administrator or the owner; avoid direct confrontations.</p><p><span id="source-block-FgIi5lmzQCSeiBKEktSP0f"></span></p><h2 id="removing-members-from-the-qq-support-group" tabindex="-1">Removing Members from the QQ Support Group <a class="header-anchor" href="#removing-members-from-the-qq-support-group" aria-label="Permalink to &quot;Removing Members from the QQ Support Group&quot;">​</a></h2><p><span class="mark-grey">#言: Clear out members who have not spoken for a week, once a week. Those wanting further study can message sky to join a dedicated group. Could people who want to stay and help get a group title? If their problem is still unresolved, they can rejoin.</span></p><p><span class="mark-grey">#东: What are the removal criteria? Not speaking for a long time? Keeping only a fixed roster?</span></p><p><span class="mark-grey">#disadvantage: In theory, people can be removed once troubleshooting is finished. Those wanting a deeper understanding can stay or move to another group.</span></p><p><span id="source-block-K1QLU97ywaQqerFz7hD7qK"></span></p><h2 id="customer-support-q-a-sign-up" tabindex="-1">Customer Support / Q&amp;A Sign-up <a class="header-anchor" href="#customer-support-q-a-sign-up" aria-label="Permalink to &quot;Customer Support / Q&amp;A Sign-up&quot;">​</a></h2><p>jmy</p><p>东弓（东弓与葛冰之）</p><p>NH（D-15191）</p><p>凯尔希思衡托</p><p>SSnighter</p><p>Disadvantages</p><p>泥岩___（沃沃头子）</p><p><span id="source-block-n2NeK8zgbi9dRIjBQcTKpl"></span></p><h2 id="customer-support-q-a-roster" tabindex="-1">Customer Support / Q&amp;A Roster <a class="header-anchor" href="#customer-support-q-a-roster" aria-label="Permalink to &quot;Customer Support / Q&amp;A Roster&quot;">​</a></h2><p><span id="source-block-9fU6RZ0Clraa1KB7ThLxkv"></span></p><h2 id="backup-q-a-roster" tabindex="-1">Backup Q&amp;A Roster <a class="header-anchor" href="#backup-q-a-roster" aria-label="Permalink to &quot;Backup Q&amp;A Roster&quot;">​</a></h2></div>',1)])])}const m=t(n,[["render",r]]);export{c as __pageData,m as default};
